import{z as n,x as p,o as l,c as B,q as t,j as s,D as e,d as A,s as i,S as o,b as E}from"./chunks/framework.C8m1ZpeB.js";const u=JSON.parse('{"title":"自博弈","description":"","frontmatter":{"title":"自博弈","date":"2026-09-08T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/self-play-lm.md","filePath":"llm/self-play-lm.md","lastUpdated":1791063341000}'),d={name:"llm/self-play-lm.md"};function h(m,a,P,D,f,N){const r=p("Mermaid");return l(),B("div",null,[a[2]||(a[2]=t('<h1 id="自博弈" tabindex="-1">自博弈 <a class="header-anchor" href="#自博弈" aria-label="Permalink to &quot;自博弈&quot;">​</a></h1><div class="epigraph"><p>没有人类示范的走子，两个副本对弈，用谁赢了当奖励；语言上的自博弈要把「赢」定义成可检验的事件。</p><footer>—— Silver 等 AlphaZero；Chen 等 SPIN；语言模型上的自博弈偏好优化</footer></div><p><a href="/llm/nash-learning-hf">上一课</a>在偏好支付下求均衡。缺口是：很多任务的胜负不必经过偏好模型——棋、代码测试、数学对错。自博弈让当前策略与自己（或历史）对阵，用环境输赢更新。AlphaZero 是原型；SPIN 把「对手」写成上一轮策略，用 DPO 式损失让当前模型打赢旧自己。本课写 LM 自博弈，不重写 <a href="/llm/grpo">GRPO</a>。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>人类比较覆盖不到的能力（超人类棋力、长证明）无法从示范模仿。自博弈的条件是：<strong>对称、可判定的输赢。</strong></p><p><span class="marginnote">「对称、可判定」翻译成大白话：双方用同一套规则玩，且终局有机械的裁判——棋盘规则、单元测试或标准答案。开放式聊天两条都不满足，所以不能直接拿来当自博弈的支付。</span> 棋满足；开放聊天不满足——两个助手互评「谁更有用」会退化成自奖励。LM 上合法的自博弈：(1) 双人游戏或辩论（下一课）；(2) 对同一可验证题，当前 \\(\\pi\\) 对历史 \\(\\pi_{\\mathrm{old}}\\) 比谁的 \\(R\\) 高，再造成对；(3) SPIN：把 SFT 当对手，迭代让金标人类回答赢过上一轮模型的输出。</p><p>没有判定器的自博弈，只是两个模型互相吹捧。本课把判定器当一等公民，与 <a href="/llm/verifiable-reward">可验证奖励</a> 对齐。对手若永远是当前 \\(\\pi\\) 的瞬时副本，梯度对称、进步慢；混入落后 checkpoint 才能提供可打赢的负例。</p><h3 id="spin-不是-alphazero" tabindex="-1">SPIN 不是 AlphaZero <a class="header-anchor" href="#spin-不是-alphazero" aria-label="Permalink to &quot;SPIN 不是 AlphaZero&quot;">​</a></h3><p>AlphaZero 有 MCTS 与精确规则。SPIN 没有搜索树，用偏好损失打赢旧策略。能力上限受裁判（往往是模型自己）限制。不要把指令模型的 SPIN 曲线写成「达到超人类」。</p><p><span class="marginnote">历史对手池（PFSP）防止循环克制：只打赢昨天的自己，可能遗忘前天会的策略。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>可验证：对每个 \\(x\\)，当前与对手各采样，比较 \\(R\\)，构 \\((y_w,y_l)\\)，DPO 或直接对赢家做 REINFORCE。游戏：在环境里对弈，终局 \\(\\pm 1\\)，PPO。SPIN：用上一轮模型生成 \\(y\\) 当负例，与 SFT 数据的金标回答组成对，训练使 \\(\\pi\\) 偏好金标回答。对手更新频率是超参：太快不稳定，太慢过拟合一个对手。</p><p><span class="marginnote">数字感受一下对手更新频率：假设训练 5 轮、每轮 2000 步。每 100 步换一次对手，对手刚被打赢就退役，训练信号抖动；整轮只换一次，后半段对手早被碾压，负例失效。常见做法是每 500 到 1000 步把当前模型快照塞进对手池。</span></p>',13)),(l(),s(o,null,{default:e(()=>[i(r,{id:"mermaid-37",class:"mermaid",graph:"flowchart%20TD%0A%20%20PI%5B%22%E5%BD%93%E5%89%8D%20%CF%80%22%5D%20--%3E%20ENV%5B%22%E7%8E%AF%E5%A2%83%20%2F%20%E6%A0%A1%E9%AA%8C%E5%99%A8%20%2F%20%E5%AF%B9%E5%BC%88%22%5D%0A%20%20OPP%5B%22%E5%AF%B9%E6%89%8B%EF%BC%9A%E5%8E%86%E5%8F%B2%20%CF%80%20%E6%88%96%E8%87%AA%E5%B7%B1%22%5D%20--%3E%20ENV%0A%20%20ENV%20--%3E%20W%5B%22%E5%8F%AF%E5%88%A4%E5%AE%9A%E8%BE%93%E8%B5%A2%22%5D%0A%20%20W%20--%3E%20UPD%5B%22DPO%20%E6%88%96%E7%AD%96%E7%95%A5%E6%A2%AF%E5%BA%A6%22%5D%0A%20%20UPD%20--%3E%20PI%0A%20%20UPD%20--%3E%20POOL%5B%22%E5%AF%B9%E6%89%8B%E6%B1%A0%22%5D%0A"})]),fallback:e(()=>[...a[0]||(a[0]=[A(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=E("h2",{id:"机制",tabindex:"-1"},[A("机制 "),E("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[4]||(a[4]=E("p",null,"自博弈提供无限新对局，覆盖随 \\(\\pi\\) 移动。非传递游戏会循环；语言偏好更非传递，所以开放域自博弈危险。可验证域传递性较好（对就是对），自博弈近似「用旧策略当负例的 RFT」，与拒绝采样数据循环近亲。真正的新能力来自探索是否找到校验器仍接受的新解法。",-1)),a[5]||(a[5]=E("p",null,[E("span",{class:"marginnote"},"与 Nash 学习的差别：自博弈的支付是环境，Nash 的支付是偏好模型。可以嵌套：环境赢 + 偏好做平局打破。")],-1)),a[6]||(a[6]=E("p",null,"SPIN 的单轮迭代具体怎么转：",-1)),(l(),s(o,null,{default:e(()=>[i(r,{id:"mermaid-50",class:"mermaid",graph:"flowchart%20TD%0A%20%20T%5B%22%E7%AC%AC%20t%20%E8%BD%AE%E6%A8%A1%E5%9E%8B%EF%BC%9A%E5%AF%B9%E6%89%8B%22%5D%20--%3E%20GEN%5B%22%E5%AF%B9%E9%A2%98%E7%9B%AE%20x%20%E9%87%87%E6%A0%B7%E6%97%A7%E5%9B%9E%E7%AD%94%EF%BC%9A%E5%88%A4%E8%BE%93%E4%BE%A7%22%5D%0A%20%20GOLD%5B%22SFT%20%E6%95%B0%E6%8D%AE%E7%9A%84%E9%87%91%E6%A0%87%E4%BA%BA%E7%B1%BB%E5%9B%9E%E7%AD%94%EF%BC%9A%E5%88%A4%E8%B5%A2%E4%BE%A7%22%5D%20--%3E%20PAIR%5B%22%E7%BB%84%E6%88%90%E5%81%8F%E5%A5%BD%E5%AF%B9%EF%BC%9A%E9%87%91%E6%A0%87%20vs%20%E6%97%A7%E8%BE%93%E5%87%BA%22%5D%0A%20%20GEN%20--%3E%20PAIR%0A%20%20PAIR%20--%3E%20TRAIN%5B%22%E8%AE%AD%E7%BB%83%EF%BC%9A%E8%AE%A9%E6%A8%A1%E5%9E%8B%E5%81%8F%E5%A5%BD%E9%87%91%E6%A0%87%E5%9B%9E%E7%AD%94%22%5D%0A%20%20TRAIN%20--%3E%20NEXT%5B%22%E5%BE%97%E5%88%B0%E7%AC%AC%20t%2B1%20%E8%BD%AE%E6%A8%A1%E5%9E%8B%22%5D%0A%20%20NEXT%20--%3E%20T%0A"})]),fallback:e(()=>[...a[1]||(a[1]=[A(" Loading... ",-1)])]),_:1})),a[7]||(a[7]=t('<p><span class="marginnote">常见误区：以为自博弈是「左右互搏就能无限变强」。实际上进步的上限是校验器：它能接受的解法空间就是模型能探索到的天花板。校验器有漏洞时，模型可能学会钻空子的「新解法」——这不是变强，是过拟合裁判。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>辩论把「赢」交给人类或弱裁判看论证，下一课专门写监督含义。安全自博弈（红队 vs 蓝队）需要小心：攻击策略可能外溢到产品。代码 / 数学是主场。下一课辩论把自博弈接到可扩展监督。</p><p>对手池要混入落后 checkpoint，避免只打赢瞬时自己。没有判定器的互评会退化成自奖励，本课不覆盖。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>LM 自博弈要求对称且可判定的赢；开放互评会退化成自奖励。</li><li>SPIN 打赢旧自己，不是 AlphaZero；上限受裁判限制。</li><li>对手池防止循环克制与遗忘。</li><li>可验证 \\(R\\) 是最干净的支付。</li><li>出处：Silver 等 AlphaZero；Chen 等 SPIN；对照 Munos NLHF。</li></ul>',6))])}const S=n(d,[["render",h]]);export{u as __pageData,S as default};
